#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ufbx.h"

typedef struct json_buffer { char *data; size_t length, capacity; int failed; } json_buffer;
typedef struct binary_buffer { void *data; size_t length; } binary_buffer;

static char *g_attribute_result;
static size_t g_attribute_result_length;
static binary_buffer *g_attribute_buffers;
static size_t g_attribute_buffer_count;
static char g_attribute_error[512];
static size_t g_attribute_error_length;

static int checked_add(size_t a,size_t b,size_t*out){if(a>SIZE_MAX-b)return 0;*out=a+b;return 1;}
static int checked_mul(size_t a,size_t b,size_t*out){if(a&&b>SIZE_MAX/a)return 0;*out=a*b;return 1;}
static int jb_reserve(json_buffer*b,size_t extra){size_t required;if(b->failed)return 0;if(!checked_add(b->length,extra,&required)||!checked_add(required,1,&required)){b->failed=1;return 0;}if(required<=b->capacity)return 1;size_t capacity=b->capacity?b->capacity:4096;while(capacity<required){size_t next=capacity<16*1024*1024?capacity*2:capacity+16*1024*1024;if(next<=capacity){b->failed=1;return 0;}capacity=next;}char*data=(char*)realloc(b->data,capacity);if(!data){b->failed=1;return 0;}b->data=data;b->capacity=capacity;return 1;}
static void jb_raw(json_buffer*b,const char*s){size_t n=strlen(s);if(!jb_reserve(b,n))return;memcpy(b->data+b->length,s,n);b->length+=n;b->data[b->length]='\0';}
static void jb_char(json_buffer*b,char c){if(!jb_reserve(b,1))return;b->data[b->length++]=c;b->data[b->length]='\0';}
static void jb_u64(json_buffer*b,uint64_t v){char s[32];snprintf(s,sizeof(s),"%llu",(unsigned long long)v);jb_raw(b,s);}
static void jb_string_n(json_buffer*b,const char*s,size_t n){jb_char(b,'"');for(size_t i=0;i<n;i++){unsigned char c=(unsigned char)s[i];if(c=='"'||c=='\\'){jb_char(b,'\\');jb_char(b,(char)c);}else if(c=='\n')jb_raw(b,"\\n");else if(c=='\r')jb_raw(b,"\\r");else if(c=='\t')jb_raw(b,"\\t");else if(c<0x20)jb_raw(b,"?");else jb_char(b,(char)c);}jb_char(b,'"');}
static void jb_string(json_buffer*b,ufbx_string s){jb_string_n(b,s.data?s.data:"",s.data?s.length:0);}
static void set_error_text(const char*text){snprintf(g_attribute_error,sizeof(g_attribute_error),"%s",text);g_attribute_error_length=strlen(g_attribute_error);}
static void set_ufbx_error(const char*prefix,const ufbx_error*e){const char*d=e&&e->description.data?e->description.data:"unknown parser error";snprintf(g_attribute_error,sizeof(g_attribute_error),"%s: %.*s",prefix,e?(int)e->description.length:20,d);g_attribute_error_length=strlen(g_attribute_error);}
static void clear_attributes(void){free(g_attribute_result);g_attribute_result=NULL;g_attribute_result_length=0;for(size_t i=0;i<g_attribute_buffer_count;i++)free(g_attribute_buffers[i].data);free(g_attribute_buffers);g_attribute_buffers=NULL;g_attribute_buffer_count=0;}
static int attribute_fail(const char*message){set_error_text(message);clear_attributes();return 0;}
static int load_scenes(const void*data,size_t size,ufbx_scene**source,ufbx_scene**normalized){ufbx_load_opts a={0};a.retain_dom=true;a.load_external_files=false;a.ignore_embedded=true;ufbx_error e1;*source=ufbx_load_memory(data,size,&a,&e1);if(!*source){set_ufbx_error("ufbx source parse failed",&e1);return 0;}ufbx_load_opts b=a;b.target_axes=ufbx_axes_right_handed_y_up;b.target_unit_meters=0.001;b.space_conversion=UFBX_SPACE_CONVERSION_MODIFY_GEOMETRY;ufbx_error e2;*normalized=ufbx_load_memory(data,size,&b,&e2);if(!*normalized){set_ufbx_error("ufbx normalization failed",&e2);ufbx_free_scene(*source);*source=NULL;return 0;}return 1;}
static uint64_t source_id(const ufbx_element*e){return e&&e->dom_node&&e->dom_node->values.count?(uint64_t)e->dom_node->values.data[0].value_int:e?e->element_id:0;}
static int allocate_buffer(size_t index,size_t length){void*p=length?malloc(length):NULL;if(length&&!p)return 0;g_attribute_buffers[index].data=p;g_attribute_buffers[index].length=length;return 1;}
static int add_total_bytes(size_t*total,size_t value){return value<=268435456&&checked_add(*total,value,total)&&*total<=536870912;}
static int validate_common(bool exists,size_t values,size_t indices,size_t reals,size_t expected,size_t corners){if(!exists)return 1;if(reals!=expected||indices!=corners)return 0;if(values>67108864||(corners&&values==0))return 0;return 1;}
static int copy_indices(const ufbx_uint32_list*source,size_t value_count,size_t output_index,size_t*total){size_t length;if(!checked_mul(source->count,sizeof(uint32_t),&length)||!add_total_bytes(total,length)||!allocate_buffer(output_index,length))return 0;uint32_t*out=(uint32_t*)g_attribute_buffers[output_index].data;for(size_t i=0;i<source->count;i++){uint32_t value=source->data[i];if(value>=value_count)return 0;out[i]=value;}return 1;}
static void write_attribute_metadata(json_buffer*j,bool unique,size_t value_count,size_t reals,size_t values_index,size_t indices_index){jb_raw(j,"{\"sourceDomain\":\"");jb_raw(j,unique?"control-point":"polygon-vertex");jb_raw(j,"\",\"referenceMode\":\"indexed-value-table\",\"valueCount\":");jb_u64(j,value_count);jb_raw(j,",\"valueReals\":");jb_u64(j,reals);jb_raw(j,",\"uniquePerVertex\":");jb_raw(j,unique?"true":"false");jb_raw(j,",\"bufferIndices\":{\"values\":");jb_u64(j,values_index);jb_raw(j,",\"indices\":");jb_u64(j,indices_index);jb_raw(j,"}}");}

static int emit_vec2(json_buffer*j,const ufbx_vertex_vec2*a,size_t corners,size_t*buffer_index,size_t*total){if(!a->exists){if(j)jb_raw(j,"null");return 1;}if(!validate_common(a->exists,a->values.count,a->indices.count,a->value_reals,2,corners)||(a->values.count&&!a->values.data)||(a->indices.count&&!a->indices.data))return 0;size_t length;if(!checked_mul(a->values.count,2*sizeof(double),&length)||!add_total_bytes(total,length)||!allocate_buffer(*buffer_index,length))return 0;double*out=(double*)g_attribute_buffers[*buffer_index].data;for(size_t i=0;i<a->values.count;i++){double x=a->values.data[i].x,y=a->values.data[i].y;if(!isfinite(x)||!isfinite(y))return 0;out[i*2]=x==0.0?0.0:x;out[i*2+1]=y==0.0?0.0:y;}size_t values_index=(*buffer_index)++,indices_index=*buffer_index;if(!copy_indices(&a->indices,a->values.count,indices_index,total))return 0;(*buffer_index)++;if(j)write_attribute_metadata(j,a->unique_per_vertex,a->values.count,a->value_reals,values_index,indices_index);return 1;}
static int emit_vec3(json_buffer*j,const ufbx_vertex_vec3*a,size_t corners,size_t*buffer_index,size_t*total){if(!a->exists){if(j)jb_raw(j,"null");return 1;}if(!validate_common(a->exists,a->values.count,a->indices.count,a->value_reals,3,corners)||(a->values.count&&!a->values.data)||(a->indices.count&&!a->indices.data))return 0;size_t length;if(!checked_mul(a->values.count,3*sizeof(double),&length)||!add_total_bytes(total,length)||!allocate_buffer(*buffer_index,length))return 0;double*out=(double*)g_attribute_buffers[*buffer_index].data;for(size_t i=0;i<a->values.count;i++){ufbx_vec3 v=a->values.data[i];if(!isfinite(v.x)||!isfinite(v.y)||!isfinite(v.z))return 0;out[i*3]=v.x==0.0?0.0:v.x;out[i*3+1]=v.y==0.0?0.0:v.y;out[i*3+2]=v.z==0.0?0.0:v.z;}size_t values_index=(*buffer_index)++,indices_index=*buffer_index;if(!copy_indices(&a->indices,a->values.count,indices_index,total))return 0;(*buffer_index)++;if(j)write_attribute_metadata(j,a->unique_per_vertex,a->values.count,a->value_reals,values_index,indices_index);return 1;}
static int emit_vec4(json_buffer*j,const ufbx_vertex_vec4*a,size_t corners,size_t*buffer_index,size_t*total){if(!a->exists){if(j)jb_raw(j,"null");return 1;}if(!validate_common(a->exists,a->values.count,a->indices.count,a->value_reals,4,corners)||(a->values.count&&!a->values.data)||(a->indices.count&&!a->indices.data))return 0;size_t length;if(!checked_mul(a->values.count,4*sizeof(double),&length)||!add_total_bytes(total,length)||!allocate_buffer(*buffer_index,length))return 0;double*out=(double*)g_attribute_buffers[*buffer_index].data;for(size_t i=0;i<a->values.count;i++){ufbx_vec4 v=a->values.data[i];if(!isfinite(v.x)||!isfinite(v.y)||!isfinite(v.z)||!isfinite(v.w))return 0;out[i*4]=v.x==0.0?0.0:v.x;out[i*4+1]=v.y==0.0?0.0:v.y;out[i*4+2]=v.z==0.0?0.0:v.z;out[i*4+3]=v.w==0.0?0.0:v.w;}size_t values_index=(*buffer_index)++,indices_index=*buffer_index;if(!copy_indices(&a->indices,a->values.count,indices_index,total))return 0;(*buffer_index)++;if(j)write_attribute_metadata(j,a->unique_per_vertex,a->values.count,a->value_reals,values_index,indices_index);return 1;}
static int duplicate_uv_index(const ufbx_mesh*m,size_t ordinal){for(size_t i=0;i<ordinal;i++)if(m->uv_sets.data[i].index==m->uv_sets.data[ordinal].index)return 1;return 0;}
static int duplicate_color_index(const ufbx_mesh*m,size_t ordinal){for(size_t i=0;i<ordinal;i++)if(m->color_sets.data[i].index==m->color_sets.data[ordinal].index)return 1;return 0;}
static int emit_materials(json_buffer*j,const ufbx_mesh*m,size_t*buffer_index,size_t*total){if(m->face_material.count==0){jb_raw(j,"null");return 1;}if(m->face_material.count!=m->num_faces)return 0;size_t length;if(!checked_mul(m->num_faces,sizeof(uint32_t),&length)||!add_total_bytes(total,length)||!allocate_buffer(*buffer_index,length))return 0;if(length)memcpy(g_attribute_buffers[*buffer_index].data,m->face_material.data,length);jb_raw(j,"{\"count\":");jb_u64(j,m->num_faces);jb_raw(j,",\"bufferIndex\":");jb_u64(j,*buffer_index);jb_char(j,'}');(*buffer_index)++;return 1;}
static int count_mesh_buffers(const ufbx_mesh*m,size_t*count){if(m->uv_sets.count>8||m->color_sets.count>4)return 0;size_t result=0;if(m->vertex_normal.exists)result+=2;if(m->vertex_tangent.exists)result+=2;if(m->vertex_bitangent.exists)result+=2;if(!checked_add(result,m->uv_sets.count*2,&result)||!checked_add(result,m->color_sets.count*2,&result))return 0;if(m->face_material.count)result++;return checked_add(*count,result,count);}
static int write_set_common(json_buffer*j,size_t ordinal,uint32_t source_index,ufbx_string name,bool unique,size_t values,size_t reals,size_t buffer_index){jb_raw(j,"{\"setOrdinal\":");jb_u64(j,ordinal);jb_raw(j,",\"sourceSetIndex\":");jb_u64(j,source_index);jb_raw(j,",\"name\":");jb_string(j,name);jb_raw(j,",\"sourceDomain\":\"");jb_raw(j,unique?"control-point":"polygon-vertex");jb_raw(j,"\",\"referenceMode\":\"indexed-value-table\",\"valueCount\":");jb_u64(j,values);jb_raw(j,",\"valueReals\":");jb_u64(j,reals);jb_raw(j,",\"uniquePerVertex\":");jb_raw(j,unique?"true":"false");jb_raw(j,",\"bufferIndices\":{\"values\":");jb_u64(j,buffer_index);jb_raw(j,",\"indices\":");jb_u64(j,buffer_index+1);jb_raw(j,"}}");return 1;}
static int emit_geometry(json_buffer*j,const ufbx_mesh*source,const ufbx_mesh*m,size_t*buffer_index,size_t*total){if(m->subdivision_evaluated||m->from_tessellated_nurbs||m->faces.count!=m->num_faces||m->vertex_indices.count!=m->num_indices||m->num_faces>16777215||m->num_indices>67108864)return 0;jb_raw(j,"{\"geometryObjectId\":\"");jb_u64(j,source_id(&source->element));jb_raw(j,"\",\"normalOrigin\":\"");jb_raw(j,!m->vertex_normal.exists?"absent":m->generated_normals?"ufbx-generated":"source");jb_raw(j,"\",\"normal\":");if(!emit_vec3(j,&m->vertex_normal,m->num_indices,buffer_index,total))return 0;jb_raw(j,",\"tangent\":");if(!emit_vec3(j,&m->vertex_tangent,m->num_indices,buffer_index,total))return 0;jb_raw(j,",\"bitangent\":");if(!emit_vec3(j,&m->vertex_bitangent,m->num_indices,buffer_index,total))return 0;jb_raw(j,",\"uvSets\":[");for(size_t ordinal=0;ordinal<m->uv_sets.count;ordinal++){const ufbx_uv_set*set=&m->uv_sets.data[ordinal];if(ordinal)jb_char(j,',');if(!set->vertex_uv.exists||duplicate_uv_index(m,ordinal))return 0;write_set_common(j,ordinal,set->index,set->name,set->vertex_uv.unique_per_vertex,set->vertex_uv.values.count,set->vertex_uv.value_reals,*buffer_index);if(!emit_vec2(NULL,&set->vertex_uv,m->num_indices,buffer_index,total))return 0;}jb_char(j,']');jb_raw(j,",\"colorSets\":[");for(size_t ordinal=0;ordinal<m->color_sets.count;ordinal++){const ufbx_color_set*set=&m->color_sets.data[ordinal];if(ordinal)jb_char(j,',');if(!set->vertex_color.exists||duplicate_color_index(m,ordinal))return 0;write_set_common(j,ordinal,set->index,set->name,set->vertex_color.unique_per_vertex,set->vertex_color.values.count,set->vertex_color.value_reals,*buffer_index);if(!emit_vec4(NULL,&set->vertex_color,m->num_indices,buffer_index,total))return 0;}jb_char(j,']');jb_raw(j,",\"faceMaterialSlots\":");if(!emit_materials(j,m,buffer_index,total))return 0;jb_char(j,'}');return 1;}

int fbx_attribute_parse(const void*data,size_t size){clear_attributes();g_attribute_error_length=0;ufbx_scene*s=NULL,*n=NULL;if(!load_scenes(data,size,&s,&n))return 0;size_t mesh_count=0,buffer_count=0;for(size_t i=0;i<s->elements.count;i++){const ufbx_element*e=s->elements.data[i];if(e->type!=UFBX_ELEMENT_MESH)continue;mesh_count++;const ufbx_mesh*src=(const ufbx_mesh*)e;const ufbx_mesh*m=n->meshes.data[src->typed_id];if(!count_mesh_buffers(m,&buffer_count)){ufbx_free_scene(n);ufbx_free_scene(s);return attribute_fail("FBX vertex attribute limit exceeded.");}}if(mesh_count>65536||buffer_count>2031616){ufbx_free_scene(n);ufbx_free_scene(s);return attribute_fail("FBX vertex attribute limit exceeded.");}g_attribute_buffers=(binary_buffer*)calloc(buffer_count?buffer_count:1,sizeof(binary_buffer));if(buffer_count&&!g_attribute_buffers){ufbx_free_scene(n);ufbx_free_scene(s);return attribute_fail("FBX vertex attribute buffer allocation failed.");}g_attribute_buffer_count=buffer_count;json_buffer out={0};jb_raw(&out,"{\"schema\":\"FbxRawVertexAttributes.v1\",\"geometries\":[");size_t buffer_index=0,total=0;int first=1;for(size_t i=0;i<s->elements.count;i++){const ufbx_element*e=s->elements.data[i];if(e->type!=UFBX_ELEMENT_MESH)continue;const ufbx_mesh*src=(const ufbx_mesh*)e;const ufbx_mesh*m=n->meshes.data[src->typed_id];if(!first)jb_char(&out,',');first=0;if(!emit_geometry(&out,src,m,&buffer_index,&total)){free(out.data);ufbx_free_scene(n);ufbx_free_scene(s);return attribute_fail("FBX vertex attributes are invalid.");}}jb_raw(&out,"]}");ufbx_free_scene(n);ufbx_free_scene(s);if(out.failed||buffer_index!=buffer_count){free(out.data);return attribute_fail("FBX vertex attribute result allocation failed.");}g_attribute_result=out.data;g_attribute_result_length=out.length;return 1;}
const char*fbx_attribute_result_ptr(void){return g_attribute_result;}
size_t fbx_attribute_result_len(void){return g_attribute_result_length;}
size_t fbx_attribute_buffer_count(void){return g_attribute_buffer_count;}
const void*fbx_attribute_buffer_ptr(size_t index){return index<g_attribute_buffer_count?g_attribute_buffers[index].data:NULL;}
size_t fbx_attribute_buffer_len(size_t index){return index<g_attribute_buffer_count?g_attribute_buffers[index].length:0;}
const char*fbx_attribute_error_ptr(void){return g_attribute_error;}
size_t fbx_attribute_error_len(void){return g_attribute_error_length;}
